public:
    long long maxGcdSum(vector<int>& nums, int k) {
        int n = nums.size();
        vector<long long> pref(n + 1, 0);
        for (int i = 0; i < n; i++) pref[i + 1] = pref[i] + nums[i];
        long long ans = 0;
        vector<pair<int, long long>> states;
        for (int r = 0; r < n; r++) {
            vector<pair<int, long long>> next_states;
            next_states.push_back({r, (long long) nums[r]});
            for (auto& s : states) next_states.push_back({s.first, gcd(s.second, (long long) nums[r])});
            vector<pair<int, long long>> merged;
            for (auto& s : next_states) {
                if (merged.empty() || merged.back().second != s.second) merged.push_back(s);
                else merged.back().first = min(merged.back().first, s.first);
            }
            states = merged;
            for (auto& s : states) {
                if (r - s.first + 1 >= k) {
                    long long score = s.second * (pref[r + 1] - pref[s.first]);
                    if (score > ans) ans = score;
                }
            }
        }
        return ans;
    }
};

class Solution {
    long gcd(long a, long b) {
        while (b != 0) { long t = b; b = a % b; a = t; }
        return a;
    }
    public long maxGcdSum(int[] nums, int k) {
        int n = nums.length;
        long[] pref = new long[n + 1];
        for (int i = 0; i < n; i++) pref[i + 1] = pref[i] + nums[i];
        long ans = 0;
        List<long[]> states = new ArrayList<>();
        for (int r = 0; r < n; r++) {
            List<long[]> nextStates = new ArrayList<>();
            nextStates.add(new long[]{r, nums[r]});
            for (long[] s : states) nextStates.add(new long[]{s[0], gcd(s[1], nums[r])});
            List<long[]> merged = new ArrayList<>();
            for (long[] s : nextStates) {
                if (merged.isEmpty() || merged.get(merged.size() - 1)[1] != s[1]) merged.add(s);
                else merged.get(merged.size() - 1)[0] = Math.min(merged.get(merged.size() - 1)[0], s[0]);
            }
            states = merged;
            for (long[] s : states) {
                if (r - (int) s[0] + 1 >= k) {
                    long score = s[1] * (pref[r + 1] - pref[(int) s[0]]);
                    if (score > ans) ans = score;
                }
            }
        }
        return ans;
    }
}

