var maxGcdSum = function(nums, k) {
    function gcd(a, b) {
        while (b !== 0n) { const t = b; b = a % b; a = t; }
        return a;
    }
    const n = nums.length;
    const pref = new BigInt64Array(n + 1);
    for (let i = 0; i < n; i++) pref[i + 1] = pref[i] + BigInt(nums[i]);
    let ans = 0n;
    let states = [];
    for (let r = 0; r < n; r++) {
        const x = BigInt(nums[r]);
        const nextStates = [[r, x]];
        for (const [lIdx, g] of states) nextStates.push([lIdx, gcd(g, x)]);
        const merged = [];
        for (const [lIdx, g] of nextStates) {
            if (merged.length === 0 || merged[merged.length - 1][1] !== g) merged.push([lIdx, g]);
            else merged[merged.length - 1][0] = Math.min(merged[merged.length - 1][0], lIdx);
        }
        states = merged;
        for (const [lIdx, g] of states) {
            if (r - lIdx + 1 >= k) {
                const score = g * (pref[r + 1] - pref[lIdx]);
                if (score > ans) ans = score;
            }
        }
    }
    return Number(ans);
};
